#include <limits.h>

/* C passes arrays as bare pointers — sizeof() gives you the POINTER size
   inside a function, not the array length. Always pass the length. */
int maxSubArray(const int *a, int n) {
    int best = a[0], cur = a[0];
    for (int i = 1; i < n; i++) {
        cur = (a[i] > cur + a[i]) ? a[i] : cur + a[i];
        if (cur > best) best = cur;
    }
    return best;
}

/* Prefix sums. Use long long: int sums overflow at ~2.1e9, silently. */
void prefix(const int *a, int n, long long *pre) {
    pre[0] = 0;
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
    /* sum of a[l..r] == pre[r + 1] - pre[l] */
}

/* Two pointers on a sorted array. */
int twoSumSorted(const int *a, int n, int target, int *i_out, int *j_out) {
    int i = 0, j = n - 1;
    while (i < j) {
        int s = a[i] + a[j];
        if (s == target) { *i_out = i; *j_out = j; return 1; }
        if (s < target) i++; else j--;
    }
    return 0;
}

