#include <string.h>
#include <ctype.h>

/* A C string is a char array ending in '\0'. strlen walks to find that
   terminator, so calling it inside a loop condition makes the loop O(n^2). */
size_t n = strlen(s);          /* compute ONCE */
for (size_t i = 0; i < n; i++) { /* ... */ }

/* Palindrome, two pointers, skipping non-alphanumerics. */
int isPalindrome(const char *s) {
    int i = 0, j = (int) strlen(s) - 1;
    while (i < j) {
        while (i < j && !isalnum((unsigned char) s[i])) i++;
        while (i < j && !isalnum((unsigned char) s[j])) j--;
        if (tolower((unsigned char) s[i]) != tolower((unsigned char) s[j])) return 0;
        i++; j--;
    }
    return 1;
}

/* Anagram via a 26-slot count. Cast to unsigned char before ctype calls:
   passing a negative char is undefined behaviour. */
int isAnagram(const char *a, const char *b) {
    if (strlen(a) != strlen(b)) return 0;
    int cnt[26] = {0};
    for (int i = 0; a[i]; i++) { cnt[a[i] - 'a']++; cnt[b[i] - 'a']--; }
    for (int i = 0; i < 26; i++) if (cnt[i]) return 0;
    return 1;
}

