/* C has no vector, map or set. The standard library gives you qsort and
   bsearch, and that is essentially it. Knowing what to build is the skill. */
#include <stdlib.h>

/* Growable array: double the capacity so n appends stay amortised O(1). */
typedef struct { int *data; size_t len, cap; } Vec;

void vec_push(Vec *v, int x) {
    if (v->len == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        int *grown = realloc(v->data, v->cap * sizeof *v->data);
        if (!grown) { free(v->data); exit(1); }   /* realloc can fail; the old
                                                     pointer is still valid */
        v->data = grown;
    }
    v->data[v->len++] = x;
}

void vec_free(Vec *v) { free(v->data); v->data = NULL; v->len = v->cap = 0; }

/* qsort needs a comparator returning <0 / 0 / >0. Do NOT write a - b for
   ints that may be large: the subtraction itself can overflow. */
int cmp_int(const void *p, const void *q) {
    int a = *(const int *) p, b = *(const int *) q;
    return (a > b) - (a < b);
}

int a[] = {3, 1, 2};
qsort(a, 3, sizeof a[0], cmp_int);

/* Fixed-size hash set by open addressing — the usual interview stand-in
   for unordered_set. */
#define CAP 1031            /* prime, comfortably larger than n */
int keys[CAP];
char used[CAP];

void set_add(int k) {
    unsigned h = (unsigned) k % CAP;
    while (used[h] && keys[h] != k) h = (h + 1) % CAP;   /* linear probe */
    keys[h] = k; used[h] = 1;
}

