/* C has no default recursion guard and stacks are typically 1-8 MB, so deep
   recursion segfaults rather than raising an error. Prefer iteration when the
   depth can reach 10^5. */
long long fib(int n, long long *memo) {
    if (n <= 1) return n;
    if (memo[n]) return memo[n];
    return memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
}

/* Subsets: at each index, take the element or don't. The caller owns the
   buffers — there is no container to return. */
void subsets(const int *nums, int n, int i, int *cur, int curLen,
             void (*emit)(const int *, int)) {
    if (i == n) { emit(cur, curLen); return; }
    subsets(nums, n, i + 1, cur, curLen, emit);           /* skip */
    cur[curLen] = nums[i];
    subsets(nums, n, i + 1, cur, curLen + 1, emit);       /* take */
    /* nothing to undo: curLen is passed by value, which IS the backtrack */
}

/* Tail-recursive shapes are often clearer as loops in C — the compiler may
   or may not eliminate the call. */
int gcd(int a, int b) { while (b) { int t = a % b; a = b; b = t; } return a; }

