#include <stdlib.h>

typedef struct TreeNode {
    int val;
    struct TreeNode *left, *right;
} TreeNode;

void inorder(TreeNode *r, int *out, int *k) {
    if (!r) return;
    inorder(r->left, out, k);
    out[(*k)++] = r->val;
    inorder(r->right, out, k);
}

/* Iterative inorder with an explicit stack — the same shape the recursive
   version builds implicitly. */
void inorderIter(TreeNode *root, int *out, int *k) {
    TreeNode **st = malloc(1024 * sizeof *st);
    int top = -1;
    TreeNode *cur = root;
    while (cur || top >= 0) {
        while (cur) { st[++top] = cur; cur = cur->left; }
        cur = st[top--];
        out[(*k)++] = cur->val;
        cur = cur->right;
    }
    free(st);
}

int maxDepth(TreeNode *r) {
    if (!r) return 0;
    int l = maxDepth(r->left), rr = maxDepth(r->right);
    return 1 + (l > rr ? l : rr);
}

/* Post-order is the only safe order in which to free a tree: you must not
   touch a node's children after freeing the node. */
void tree_free(TreeNode *r) {
    if (!r) return;
    tree_free(r->left);
    tree_free(r->right);
    free(r);
}

