#include <stdlib.h>
#include <string.h>

/* In C, prefer bottom-up tables: no recursion depth risk, and the memory is
   explicit. Note calloc zeroes for you; malloc does NOT — reading
   uninitialised memory is the classic DP bug here. */
int climbStairs(int n) {
    if (n <= 2) return n;
    int prev = 1, cur = 2;
    for (int i = 3; i <= n; i++) {
        int next = prev + cur;      /* rolling: only two states are read */
        prev = cur; cur = next;
    }
    return cur;
}

/* 0/1 knapsack, 1-D. Iterate weight DOWNWARD so each item is used at most
   once; upward silently becomes the unbounded version. */
int knapsack(const int *wt, const int *val, int n, int cap) {
    int *dp = calloc((size_t) cap + 1, sizeof *dp);
    for (int i = 0; i < n; i++)
        for (int w = cap; w >= wt[i]; w--) {
            int cand = val[i] + dp[w - wt[i]];
            if (cand > dp[w]) dp[w] = cand;
        }
    int best = dp[cap];
    free(dp);
    return best;
}

