#include <stdlib.h>
#include <string.h>

/* A trie node is 26 child pointers plus an end flag. That is 200+ bytes per
   node on 64-bit — tries trade memory for O(len) prefix queries. */
typedef struct TrieNode {
    struct TrieNode *children[26];
    int end;
} TrieNode;

TrieNode *trie_new(void) {
    TrieNode *t = calloc(1, sizeof *t);   /* calloc: children start NULL */
    if (!t) exit(1);
    return t;
}

void trie_insert(TrieNode *root, const char *w) {
    TrieNode *cur = root;
    for (int i = 0; w[i]; i++) {
        int c = w[i] - 'a';
        if (!cur->children[c]) cur->children[c] = trie_new();
        cur = cur->children[c];
    }
    cur->end = 1;
}

static TrieNode *trie_walk(TrieNode *root, const char *s) {
    TrieNode *cur = root;
    for (int i = 0; s[i]; i++) {
        cur = cur->children[s[i] - 'a'];
        if (!cur) return NULL;
    }
    return cur;
}

int trie_search(TrieNode *root, const char *w) {
    TrieNode *n = trie_walk(root, w);
    return n && n->end;
}

int trie_starts_with(TrieNode *root, const char *p) {
    return trie_walk(root, p) != NULL;
}

void trie_free(TrieNode *t) {
    if (!t) return;
    for (int i = 0; i < 26; i++) trie_free(t->children[i]);
    free(t);
}

